    "rules": [
      {
        "id": "rule_stockout_emergency",
        "name": "Rule 1 · 大促断货与跨国调拨护栏 (Stockout Emergency)",
        "entity": "ChannelInventorySnapshot / ChannelPartner",
        "condition": "WeeksOfSupply < 1.5 OR DynamicWOS < 1.5",
        "severity": "CRITICAL",
        "hitCount": 6,
        "financialImpact": "护航黑五潜在断货营收 $1,619,170",
        "action": "自动检索同区域同电压制式 (EU_CE_230V) 且 WOS > 6.0 的富余伙伴，生成 48h 陆运调拨单并削减缺货区广告投放"
      },
      {
        "id": "rule_prior_gen_price_protection",
        "name": "Rule 2 · 老品降价价保敞口风控 (Price Protection Guardrail)",
        "entity": "ChannelInventorySnapshot -> TclProduct",
        "condition": "ModelGeneration == '2025_PriorGen' AND WeeksOfSupply > 10.0 AND PriceProtectionExposureUSD > 30,000",
        "severity": "HIGH",
        "hitCount": 7,
        "financialImpact": "规避直接降 MSRP 触发的 $766,697.60 合同价保赔付",
        "action": "严禁直接下调 65P745/55P745 批发/零售指导价；自动切换为『买电视赠/折 Q85H 声霸 OMO 套餐 + 门店导购 $25/台 Spiff』"
      },
      {
        "id": "rule_eoq_channel_stuffing",
        "name": "Rule 3 · 季末压货骗取阶梯返利拦截 (EOQ Channel Stuffing)",
        "entity": "PartnerRebateClaim -> ChannelPartner",
        "condition": "LatestPartnerWOS > 10.0 AND SellThroughRatioPct < 58.0 AND SellInAttainmentPct >= 100.0",
        "severity": "AUDIT_HOLD",
        "hitCount": 1,
        "financialImpact": "实时冻结异常阶梯返利兑付 $162,500.00 (DIST-APAC-VN01)",
        "action": "冻结财务返利发放单据，强制要求代理商真实 POS Sell-Out 动销率回升至 >=70% 后方可解冻结算"
      }
    ]
